//20240223By_zhbyjm7783 制作
//20240224By_遇知 修改目录规则，加上分卷，完善VIP标识
//202501022By_聆听月与悦 完善目录规则+简介规则（💎为付费章节，💮为免费章节）
//	发现除排行榜外均为免费分类
搜索和发现为空时，点击登录一次
必须勾选CookieJar

ruleBookInfo.intro:
&nbsp;&nbsp;
📕书      名：{{@@.book-info-top@id.bookName@text}}
✏️作      者：{{@@.book-meta@.author@text##[作者:]*}}{{'\n'+'​'}}

📄作者信息：
{{@@class.outer-intro@p@text}}
*作品总数：{{@@class.work-number@em.1@text}}
*累计字数：{{@@class.write@em@text}}
*创作字数：{{@@class.days@em@text}}天
🏷相关标签：{{@@class.book-attribute@text}}
🔥总推荐数：{{@@class.count@em.1@text}}{{'\n'+'​'}}
📜简      介：
{{@@class.intro@text}}{{'\n'+'​'}}
{{@@id.book-intro-detail@html}}

ruleToc.chapterList:
@css:
#allCatalog>.catalog-volume>label,
#allCatalog>.catalog-volume>ul
@js:
list = [];
$ = result;
for (i in $) {
    if (/volume-name/.test(String($[i]))) {
        text = "🏮〖" + String($[i].text()).replace(/订阅本卷.*/g, "").replace(/免费.*/g, "免费").trim() + "〗🏮";
        list.push({
            text: text,
            volume: true
        });
    } else {  
        $[i].select("li").forEach(a => {     
            info = String(a.select("a").attr("title")).replace(/.*时间：|章节/g, "");
            vip = /chapter-locked/.test(a.select("em"));
            text = a.select("a").text();
            href = a.select("a").attr("href");

            // 根据VIP状态选择符号
            if (vip) {
                symbol = "💎";
            } else {
                symbol = "💮";
            }

            // 计算填充空格数量，使符号与章节名称对齐
            padding = "  ".repeat(Math.max(0, text.length - symbol.length));

            // 组合符号和章节名称
            formattedText = symbol + "〖" + text + padding + "〗" + symbol;

            // 添加到列表
            list.push({   
                text: formattedText,
                href: href,
                info: info,
                vip: vip
            });
        });
    }
}
list

