push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🌊分类",null,1,1)
push("🌊全本🌊",`/full/0_{{page}}.html`,1,1)
	arList=["玄幻","武侠","都市","历史","网游","科幻","言情","其他"]
	arList.map((tag,index)=>{
		url=`/list${index+1}/{{page}}.html`;
		push(tag, url, 1, 0.25);
		});
//java.log(JSON.stringify(sort))
JSON.stringify(sort)

